package kr.signal.mealcaremacro;
import android.accessibilityservice.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.view.accessibility.*;import android.widget.*;import java.time.*;import java.time.format.*;import java.util.*;import java.util.regex.*;
public class MacroService extends AccessibilityService {
 static MacroService instance; boolean running=false; Handler h=new Handler(Looper.getMainLooper()); String pkg; LocalDate start,pending; boolean preview; Set<String> seen=new HashSet<>(),booked=new HashSet<>(); String state=""; long due,deadline; int idle,scrolls,success,skips; String lastSig=""; WindowManager wm; LinearLayout overlay; TextView info;
 static final Pattern FULL=Pattern.compile("(20\\d{2})[.\\-/년]\\s*(\\d{1,2})[.\\-/월]\\s*(\\d{1,2})");
 static final Pattern SHORT=Pattern.compile("(\\d{1,2})[.\\-/월]\\s*(\\d{1,2})(?=\\s*(?:[.(일]|픽업|$))");
 static final String PRODUCT="헬시팩(사내식당-석식용)",TAB="석식(사내식당)";
 static String norm(String s){return s==null?"":s.replaceAll("\\s+","").replace('–','-').replace('−','-');}
 static class Item{AccessibilityNodeInfo node;String text;Rect r=new Rect();Item(AccessibilityNodeInfo n,String s){node=n;text=norm(s);n.getBoundsInScreen(r);}}
 LocalDate parse(String s){Matcher m=FULL.matcher(s);try{if(m.find())return LocalDate.of(Integer.parseInt(m.group(1)),Integer.parseInt(m.group(2)),Integer.parseInt(m.group(3)));m=SHORT.matcher(s);if(m.find()){LocalDate now=LocalDate.now();LocalDate d=LocalDate.of(now.getYear(),Integer.parseInt(m.group(1)),Integer.parseInt(m.group(2)));if(d.isBefore(now.minusMonths(6)))d=d.plusYears(1);if(d.isAfter(now.plusMonths(6)))d=d.minusYears(1);return d;}}catch(Exception ignored){}return null;}
 @Override public void onServiceConnected(){instance=this;}
 @Override public void onAccessibilityEvent(AccessibilityEvent e){}
 @Override public void onInterrupt(){stop("접근성 중단");}
 @Override public void onDestroy(){stop("서비스 종료");instance=null;super.onDestroy();}
 SharedPreferences prefs(){return getSharedPreferences("run",0);}
 void log(String s){String old=prefs().getString("log","");String line=LocalTime.now().withNano(0)+" "+s;String all=line+"\n"+old;prefs().edit().putString("log",all.substring(0,Math.min(20000,all.length()))).putString("status",s).apply();if(info!=null)info.setText("예약 "+success+" · "+s);}
 void begin(String p,LocalDate d,boolean dry){if(running)return;pkg=p;start=d;preview=dry;seen.clear();booked=new HashSet<>(prefs().getStringSet("booked",Collections.emptySet()));seen.addAll(booked);pending=null;idle=scrolls=success=skips=0;lastSig="";state="OPEN";running=true;deadline=SystemClock.uptimeMillis()+20*60*1000;due=SystemClock.uptimeMillis()+1600;show();log("시작 "+d+(dry?" (탐색만)":""));h.post(tick);}
 void stop(String reason){if(!running)return;running=false;h.removeCallbacks(tick);if(pending!=null&&("RESULT".equals(state)||"CONFIRM".equals(state)))reason+=" · "+pending+" 결과 미확인, 주문 내역 확인 필요";log(reason+" / 완료 "+success+"건");if(overlay!=null){try{wm.removeView(overlay);}catch(Exception ignored){}overlay=null;info=null;}}
 void show(){wm=(WindowManager)getSystemService(WINDOW_SERVICE);overlay=new LinearLayout(this);overlay.setOrientation(0);overlay.setGravity(Gravity.CENTER_VERTICAL);overlay.setPadding(12,4,8,4);overlay.setBackgroundColor(0xee182b21);info=new TextView(this);info.setTextColor(Color.WHITE);info.setMaxLines(2);info.setTextSize(12);overlay.addView(info,new LinearLayout.LayoutParams(0,-2,1));Button b=new Button(this);b.setText("중지");b.setOnClickListener(v->stop("사용자 중지"));overlay.addView(b);WindowManager.LayoutParams lp=new WindowManager.LayoutParams(getResources().getDisplayMetrics().widthPixels*4/5,-2,WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL,PixelFormat.TRANSLUCENT);lp.gravity=Gravity.TOP|Gravity.CENTER_HORIZONTAL;try{wm.addView(overlay,lp);}catch(Exception e){overlay=null;info=null;}}
 void walk(AccessibilityNodeInfo n,List<Item> out,int depth){if(n==null||depth>40||out.size()>1500)return;if(n.isVisibleToUser()){if(n.getText()!=null)out.add(new Item(n,n.getText().toString()));if(n.getContentDescription()!=null&&!Objects.equals(n.getText(),n.getContentDescription()))out.add(new Item(n,n.getContentDescription().toString()));}for(int i=0;i<n.getChildCount();i++)walk(n.getChild(i),out,depth+1);}
 Item exact(List<Item>a,String t){for(Item i:a)if(i.text.equals(t)&&!i.r.isEmpty())return i;return null;}
 boolean contains(List<Item>a,String t){for(Item i:a)if(i.text.contains(t))return true;return false;}
 boolean tap(Item i){if(i==null||!i.node.isEnabled()||i.r.isEmpty())return false;AccessibilityNodeInfo n=i.node;for(int k=0;n!=null&&k<5;k++,n=n.getParent())if(n.isClickable()&&n.isEnabled()&&n.performAction(AccessibilityNodeInfo.ACTION_CLICK))return true;Rect r=i.r;Path path=new Path();path.moveTo(r.exactCenterX(),r.exactCenterY());return dispatchGesture(new GestureDescription.Builder().addStroke(new GestureDescription.StrokeDescription(path,0,80)).build(),null,null);}
 void next(String s,long ms){state=s;idle=0;due=SystemClock.uptimeMillis()+ms;}
 boolean move(Item i,String s){if(tap(i)){next(s,1050);return true;}return false;}
 void waitMore(){if(++idle>14){stop("화면 인식 시간 초과: "+state);return;}due=SystemClock.uptimeMillis()+500;}
 boolean swipe(boolean down){int w=getResources().getDisplayMetrics().widthPixels,hh=getResources().getDisplayMetrics().heightPixels;Path p=new Path();p.moveTo(w*.50f,hh*(down?.77f:.30f));p.lineTo(w*.50f,hh*(down?.30f:.77f));return dispatchGesture(new GestureDescription.Builder().addStroke(new GestureDescription.StrokeDescription(p,0,440)).build(),null,null);}
 String sig(List<Item>a){StringBuilder b=new StringBuilder();for(Item i:a)if(i.text.contains("픽업")||i.text.contains("헬시팩")||i.text.contains("샐러드")||i.text.contains("투고서비스"))b.append(i.text).append('@').append(i.r.top/30).append(';');return b.toString();}
 LocalDate detailDate(List<Item>a){for(Item i:a)if(i.text.contains("픽업날짜")){LocalDate d=parse(i.text);if(d!=null&&FULL.matcher(i.text).find())return d;for(Item j:a)if(FULL.matcher(j.text).find()&&Math.abs(j.r.centerY()-i.r.centerY())<110){d=parse(j.text);if(d!=null)return d;}}return null;}
 boolean closed(List<Item>a,Item product){for(Item i:a)if(i.text.equalsIgnoreCase("CLOSED")&&Math.abs(i.r.centerX()-product.r.centerX())<product.r.width()/2+40&&i.r.bottom<=product.r.top+10&&product.r.top-i.r.bottom<350)return true;return !product.node.isEnabled();}
 LocalDate cardDate(List<Item>a,Item product){if(product.text.contains("픽업")){LocalDate d=parse(product.text);if(d!=null)return d;}Item best=null;int distance=Integer.MAX_VALUE;for(Item i:a){if(!i.text.contains("픽업")||i.text.contains("픽업날짜")||parse(i.text)==null)continue;int dy=i.r.top-product.r.bottom;if(dy>=-20&&dy<350&&Math.abs(i.r.centerX()-product.r.centerX())<Math.max(product.r.width()/2,65)&&dy<distance){best=i;distance=dy;}}return best==null?null:parse(best.text);}
 void record(LocalDate d,boolean ok){seen.add(d.toString());if(ok){booked.add(d.toString());prefs().edit().putStringSet("booked",new HashSet<>(booked)).commit();success++;log(d+" 예약 완료");}else{skips++;log(d+" "+(preview?"탐색 확인":"예약 제외"));}}
 void backToList(){pending=null;performGlobalAction(GLOBAL_ACTION_BACK);next("RETURN",1100);}
 final Runnable tick=new Runnable(){public void run(){if(!running)return;try{if(SystemClock.uptimeMillis()>deadline){stop("실행 제한 도달");return;}if(SystemClock.uptimeMillis()>=due)step();}catch(Exception e){stop("오류: "+e.getClass().getSimpleName());}if(running)h.postDelayed(this,350);}};
 void step(){AccessibilityNodeInfo root=getRootInActiveWindow();if(root==null||!pkg.equals(String.valueOf(root.getPackageName()))){waitMore();return;}List<Item>a=new ArrayList<>();walk(root,a,0);
 if("RESULT".equals(state)){if(contains(a,"예약이완료되었습니다")||contains(a,"예약이완료")){record(pending,true);pending=null;Item ok=exact(a,"확인");if(!move(ok,"RETURN"))stop("예약 완료, 확인 버튼 인식 실패");return;}if(contains(a,"이미예약")||contains(a,"이미신청")){record(pending,false);pending=null;if(!move(exact(a,"확인"),"RETURN"))backToList();return;}waitMore();return;}
 if("DETAIL".equals(state)){if(!contains(a,"상세메뉴")){waitMore();return;}if(!contains(a,PRODUCT)){stop("다른 상품 상세 화면");return;}LocalDate d=detailDate(a);if(d==null){waitMore();return;}if(pending==null||!pending.equals(d)){stop("목록/상세 날짜 불일치: "+pending+" / "+d);return;}if(d.isBefore(start)||seen.contains(d.toString())){backToList();return;}
 Item reserve=exact(a,"예약하기");if(contains(a,"예약불가")||contains(a,"예약마감")||contains(a,"이미예약")||contains(a,"CLOSED")||(reserve!=null&&!reserve.node.isEnabled())){record(d,false);backToList();return;}
 if(preview){record(d,false);backToList();return;}if(reserve==null){waitMore();return;}if(exact(a,"1")==null){stop("수량 1을 확인하지 못했습니다");return;}if(!move(reserve,"RESULT")){stop("예약 버튼 클릭 실패");return;}log(d+" 예약 요청");return;}
 if(contains(a,"상세메뉴")||contains(a,"예약이완료되었습니다")){stop("예상하지 못한 상세/완료 화면");return;}
 Item tab=exact(a,TAB);if("OPEN".equals(state)||"RETURN".equals(state)){if(tab!=null){if(move(tab,"TOP")){lastSig="";scrolls=0;return;}}Item smart=exact(a,"스마트오더");if(move(smart,"OPEN"))return;waitMore();return;}
 if(tab==null){waitMore();return;}if("TOP".equals(state)){String now=sig(a);if(now.equals(lastSig)||scrolls>=35){lastSig="";scrolls=0;next("SCAN",400);return;}lastSig=now;scrolls++;swipe(false);due=SystemClock.uptimeMillis()+850;return;}
 if("SCAN".equals(state)){ArrayList<Item> products=new ArrayList<>();for(Item i:a)if(i.text.equals(PRODUCT)||i.text.startsWith(PRODUCT+"픽업"))products.add(i);products.sort(Comparator.comparingInt(i->i.r.top));for(Item i:products){LocalDate d=cardDate(a,i);if(d==null||d.isBefore(start)||seen.contains(d.toString()))continue;if(closed(a,i)){record(d,false);continue;}pending=d;if(move(i,"DETAIL"))return;stop("상품 클릭 실패: "+d);return;}
 String now=sig(a);if(now.isEmpty()){waitMore();return;}if(now.equals(lastSig)){if(++idle>=3){stop("현재 목록 탐색 종료 · 탐색/제외 "+skips+"건");return;}}else idle=0;if(++scrolls>70){stop("스크롤 제한 도달");return;}lastSig=now;swipe(true);due=SystemClock.uptimeMillis()+850;return;}
 waitMore();
 }
}